using System.Collections.Generic;

namespace BandItPlus.Cultures
{
    // Wave 4.12 (2026-05-10): Slaver/Prisoners vendor profiles. One profile per
    // bandit culture, unlocked when player reaches chief Tier-3 with that culture.
    // Spec:  docs/superpowers/specs/2026-05-10-slaver-vendor-design.md
    // Plan:  docs/superpowers/plans/2026-05-10-slaver-vendor.md
    //
    // Phase 1 ships forest_bandits as proof-of-concept. Phase 6 fills the other
    // 13 cultures using the same template + per-culture flavor pass.
    public class SlaverProfile
    {
        public string CultureId;          // matches Settlement.Culture.StringId
        public string Name;               // e.g. "Halgar the Iron-Collared"
        public string Title;              // e.g. "Captive-Trader"
        public string Backstory;          // 1-2 sentence personal history
        public string GateSpeech;         // T0 first-meet line shown via MBTextManager

        public string[] T1HeroPool;       // wanderer occupation IDs (CharacterObject StringIds)
        public string T2PrisonerCriteria; // simple filter: "tier>=2,any_kingdom", etc.
        public UniqueHeroSpec T3UniqueHero; // synthesized named Hero spawned by SlaverHeroRegistry

        public string[] TroopT1;          // troop CharacterObject StringIds
        public string[] TroopT2;
        public string[] TroopT3;

        public SlaverCompoundQuest QuestT1;  // 2 objectives
        public SlaverCompoundQuest QuestT2;  // 3 objectives
        public SlaverCompoundQuest QuestT3;  // 4 objectives

        // Wave 4.12 cellar flavor (2026-05-11): atmospheric prose shown when the player
        // asks the slaver "What's down in your cellar?" (trust >= 2 dialog option).
        // Pure narrative — no mechanic. Reinforces the slaver's weight in the world.
        public string CellarFlavor;

        // Wave 4.13 chat-prose (2026-06-06): per-slaver authored prose for the
        // "Tell me about yourself" and "What news on the road?" Tier-3 chat lines.
        // Pure narrative; shown via InformationManager.ShowInquiry as title + body.
        public string SelfStoryTitle;     // popup title for "tell me about yourself"
        public string SelfStoryBody;      // popup body — authored monologue
        public string NewsRumorsTitle;    // popup title for "what news on the road"
        public string NewsRumorsBody;     // popup body — authored road-intel monologue
    }

    public class UniqueHeroSpec
    {
        public string Name;               // override name post-synthesis
        public string CharacterTemplateId; // CharacterObject StringId to clone for equipment + skills
        public string Backstory;          // shown on hero-pick popup
    }

    public class SlaverCompoundQuest
    {
        public string IntroText;          // slaver speech offering quest (dialog body)
        public string ThanksText;         // turn-in line
        public ObjectiveSpec[] Objectives;
        public int RewardGold;            // 2000 / 5000 / 10000 typical
    }

    public class ObjectiveSpec
    {
        public ObjectiveKind Kind;
        public string TargetId;           // hero StringId for Capture (or "RUNTIME_PICK"); item id for Materials
        public string CultureFilter;      // for Kill objectives: "battania", "*", etc.
        public int Count;
        public string Description;        // shown in journal entry text
    }

    public enum ObjectiveKind { Kill, Capture, Prisoners, Materials }

    public static class SlaverProfiles
