        public static readonly Dictionary<string, SlaverProfile> ByCultureId =
            new Dictionary<string, SlaverProfile>
        {
            ["forest_bandits"] = new SlaverProfile
            {
                CultureId = "forest_bandits",
                Name = BandItPlus.Localization.Get("bp_slaverprofiles_001", "Halgar the Iron-Collared"),
                Title = BandItPlus.Localization.Get("bp_slaverprofiles_002", "Captive-Trader"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_014", "Once chained himself in a {CULTURE_BAT} noble's grain-cellar; got out the hard way and never let himself or anyone else forget what coin can do to a man."),
                GateSpeech = "{=bp_slaverprofiles_003}Chief sent you? Hm. Walk careful. I deal in flesh and steel — and I weigh both before I trust either.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_015", "Halgar opens the hatch. The smell rises first — damp earth, old straw, men. Five candles burn in clay holders, throwing the cage-shadows long. A {CULTURE_BAT} merchant in chains looks up; his eyes are tired in the way no rest can fix. A {CULTURE_VLA} sergeant's daughter sits on a pallet, knees pulled in. Halgar nods to a third cage at the back, hidden behind a hanging cloak. \"That one I keep for paying customers,\" he says. \"You're not there yet.\""),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_004", "What Halgar Says"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_016", "You asked. Most don't. Most look at the cages and decide the answer already, and walk off with their pity tucked under their arm like a loaf they paid for. Sit down. The trade pays a man what he was already owed, and I'll tell you how I came to collect.\n\nThere was a noble in Battania once — fat in the belt, fat in the voice — who put me down a grain-cellar with a chain through my collarbone for the price of a stolen ox. Four months. You learn things down there. You learn that hunger is a kind of clock. You learn the shape of your own ribs through your shirt. You learn that a man with the key is just a man with the key, and keys can be taken if you're patient and the hinge is old enough. I got out the hard way. I left the noble in the cellar with my chain.\n\nAfter that I tried the honest roads. Smith's apprentice, drover, hauler for a {CULTURE_VLA} caravan. Coin came thin and went thinner, and every lord I bowed to had the same wet smile as the one in the cellar. So I stopped bowing. I cut a strap off a slaver's wagon outside <span style=\"BandItPlus.Place\">Pen Cannoc</span> and bought my first three souls with what was in the strongbox underneath. That was the ledger I started. I've been keeping it since.\n\nI don't tell myself I'm a kind man. Kindness is a coin I spent down in the dark and never got back. What I am is honest about the weight. A man in chains is a man in chains — I was one, I sell one, the iron doesn't care whose neck it sits on. The trade pays because the world is built on it, friend. Lords just hide their cellars better than I do.\n\nSo that's what brought me. A cellar, a chain, a hinge that gave. Some men come out of the dark and swear it off. I came out of the dark and learned the price of it, and now I charge it. Don't look surprised. You asked."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_005", "What Halgar Hears"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_017", "The <span style=\"BandItPlus.Place\">Brionne</span> road runs fat right now. {CULTURE_VLA} wool carts move east with four guards, sometimes three, and the drivers drink at the last waystation before the woods. I had a man clear two of those carts last moon — kept the drivers, sold the outriders to a foundry-master in <span style=\"BandItPlus.Place\">Galend</span> who asks no questions about a missing tongue. That foundry buys steady. He pays in silver, not promises, and he likes his stock young enough to last the bellows ten winters.\n\n<span style=\"BandItPlus.Name\">Lord Caladog</span> of the Wolfskins is bleeding men. His warband took a mauling near Llugwy Ford and he's pulled his patrols north to lick the wound, so the southern trails between <span style=\"BandItPlus.Place\">Pen Cannoc</span> and the lowland villages sit open. A {CULTURE_BAT} girl alone on those paths is coin walking on two legs. I've taken three this season off that stretch and the chief still hasn't sent a single rider to ask after them. A lord who cannot count his own farmers is a lord I thank quietly.\n\nThere's a {CULTURE_KHU} flesh-broker working out of <span style=\"BandItPlus.Place\">Sanala</span> calling himself Yerlan. He buys in lots of five or more, pays under-market, but he moves the stock east before any clan-rider can come looking. I dealt with him twice. The second time he tried to short me a denar a head and I broke his cousin's hand on the table — we settled fair after that. If you have bodies to move quick and don't care for top coin, he's the line. If you want full price, ride to Epicrotea instead; the arena-keepers there still pay in old gold and they don't haggle over teeth.\n\nWord is the {CULTURE_STU} timber-caravans running down from <span style=\"BandItPlus.Place\">Varcheg</span> are pulling thin escorts this season — the war up north ate their hired swords. Two wagons, six guards, mostly drunk boys with spears they don't know how to hold. A man with twenty blades and a quiet wood could clear one in an afternoon and walk away with three carpenters and a fletcher worth their weight. Carpenters fetch double from the {CULTURE_ASE} forts rebuilding their gates. I'd take that work myself if I weren't sitting on stock already.\n\nOne last thing. There's a hedge-priest moving village to village in the {CULTURE_BAT} hills, buying chained folk and setting them loose — pays in coin he begs off {CULTURE_VLA} merchants. Sentimental fool, but his coin spends the same as any. I sold him an old man last week who wouldn't have lasted the road anyway. He thanked me. I took the silver. The trade doesn't care whose hand it passes through, only that the hand is open."),

                T1HeroPool = new[] { "wanderer_battanian_3", "wanderer_battanian_5", "wanderer_imperial_2" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec
