            // ================================================================
            // Phase 6 (2026-05-10): remaining 13 cultures. Concise entries — same
            // structure as forest_bandits but compact prose for shipping all at once.
            // Each culture's quest filter targets its in-fiction antagonist kingdom;
            // materials are biome-appropriate (hardwood/fur/salt/flax_bundle/etc).
            // ================================================================

            ["looters"] = new SlaverProfile
            {
                CultureId = "looters", Name = BandItPlus.Localization.Get("bp_slaverprofiles_018", "Skreg One-Ear"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_019", "Pit-Master"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_020", "Was nobody's son; sold his own brother and never spoke of it again. Trades in the desperate."),
                GateSpeech = "{=bp_slaverprofiles_021}Chief letting you in here? Bold. Try not to bleed on the floor.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_022", "Skreg leads you down a stair carved into raw dirt. Three pits, lids made of warped boards. Something moves in the second one. He doesn't say what. The fourth pit is empty — \"That one's yours if you ever stop being useful,\" he says, and isn't joking."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_023", "What Skreg Says"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_024", "You want the story? Cheap question. The answer is cheaper. I was nobody's son. My mother died on the road and the road did not stop for her. I learned early that a body is only worth what someone will hand you for it, and most days that is less than bread.\n\nI had a brother once. Younger. He cried easier than me, which is to say he cried at all. A caravan came through with empty cages and a full purse, and I led him to the cage myself. I told him it was a game. I took the coin. I bought bread, and a knife, and a place by a fire where no one knew my face. I have never said his name out loud since. I will not say it for you either.\n\nAfter that the trade was simple. The pit asked nothing I had not already given. I learned the marks — the ones who run, the ones who fight, the ones who go quiet and wait to die. The quiet ones sell best. {CULTURE_EMP}s especially. They were raised believing somebody would come for them, so they keep their teeth and their backs straight in the cage. A straight back is silver on the line.\n\nI do not love it. I do not hate it. A man who hates his work drinks his coin and ends up in his own chains. I keep the ledger. I keep the cages. I keep the road from coming back for me the way it came for my mother. That is what pays a man into this trade — not greed, not cruelty. The road. The road is always behind you, and the only thing that puts distance between you and it is somebody else's neck under your hand.\n\nSo. You asked. Now stand off the floor and tell me what you came to buy."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_025", "Word from the Road"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_026", "{CULTURE_EMP} caravans run the southern road from <span style=\"BandItPlus.Place\">Amitatys</span> these last weeks. Thin guards. The Senate pays in promises now, and a captain paid in promises hires fewer spears. I took three drovers off that road last moon. Two went to the pit. One I sold whole to a man who would not give his name.\n\nThere is a noble out of <span style=\"BandItPlus.Place\">Phycaon</span> who lost his brother to bandits and has not slept since. He rides with six men and grief makes him stupid. Grief and a heavy purse — I have seen both on the same horse before. If a pit-master had ambition, that one rides alone past the broken mile-stone every third day at dusk. I am only saying what the road says.\n\nRazih buys quiet. The flesh-trade there moves through the back of a tanner's shop — you knock twice, you say the word *salt*, you do not look at the men in the corner. They pay in dirhems, weighed not counted. I will not name the tanner. A man who names tanners ends in a tannery.\n\nThere is a new one working the eastern stretch. Calls himself Vellig, says he was a caravan-master once. He is not. He is some lord's bastard who learned the trade in a week and thinks chains are rope. He bought a {CULTURE_BAT} girl off me last month for half her worth and I let him, because a fool with coin is the best customer a pit-master can hope for. He will be dead by harvest. His coin will not.\n\nThe {CULTURE_KHU} are moving south of <span style=\"BandItPlus.Place\">Odokh</span> and the steppes are emptying out — herder families on the road with no spear between them, only the old man and the boy. That is not trade, that is harvest. I take what the road gives. My brother taught me that, though he did not mean to."),
                T1HeroPool = new[] { "wanderer_imperial_2", "wanderer_imperial_5" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_027", "Drust the Lung-Cut"), CharacterTemplateId = "looter", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_028", "Survived a hanging once and the rope marks never faded.") },
                TroopT1 = new[] { "looter" }, TroopT2 = new[] { "looter" }, TroopT3 = new[] { "looter" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_029}Three {CULTURE_EMP} dogs. Six prisoners. Easy work for a fresh hand.", "{=bp_slaverprofiles_030}Skreg counts your coin twice. Pays anyway.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 3, Description = BandItPlus.Localization.Get("bp_hcs_015", "Kill 3 lords (any culture)") },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_031}This one's name is on the slip. Alive. Five more bodies. Twenty hardwood for the cages.", "{=bp_slaverprofiles_032}Skreg grunts approval.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked lord ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 5, Description = "Kill 5 lords" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 20, Description = "Gather 20 hardwood" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_033}Last one. Ten dead, fifteen alive, a lord captured, forty hardwood.", "{=bp_slaverprofiles_034}Skreg opens the cellar.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 10, Description = "Kill 10 lords" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked lord ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 40, Description = "Gather 40 hardwood" }),
            },

            ["mountain_bandits"] = new SlaverProfile
            {
                CultureId = "mountain_bandits", Name = BandItPlus.Localization.Get("bp_slaverprofiles_035", "Volk Stone-Tongue"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_036", "Highrunner"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_037", "Once held a pass against three caravans alone; the survivors named him. He sells men because beasts are cheaper."),
                GateSpeech = "{=bp_slaverprofiles_038}Hm. Chief's man. Down here we don't trust easy. Show me work.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_039", "The cellar is hewn from the mountain itself, cold even in summer. Volk's prisoners sit huddled in furs — he keeps them alive better than most, because frozen meat sells for less. A {CULTURE_STU} thane chained at the back recognizes you; nods once. He's been counting days. Volk pretends not to notice the count."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_040", "The Highrunner's Arithmetic"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_041", "The pass took me first. Three caravans came up the road that winter, and I was the only blade on the rocks. I held the choke for two days. When the survivors crawled out, they gave me a name — Stone-Tongue — because I would not speak terms, only count the dead.\n\nAfter that the work was simple. A man learns what his hands do best, and mine break the line where it bends. I tried beasts for a season — goats, a pair of mules — and the math was thin. Beasts eat through the snow and die on the slope. A chained man walks himself down to the buyer and carries his own weight in coin.\n\nSo I sell men. {CULTURE_STU} mostly. They come up these passes thinking the cold knows them. The cold knows nothing. I know the cold. I take them off the road before the road takes them, and I march them south to a ledger that pays in silver, not in stories.\n\nYou want the honest piece — there's no debt behind it. No brother lost, no woman buried. I looked at the trade and saw what it was. Cheaper than herding. Quieter than war. A mark on a wrist holds longer than a brand on a hide. That is what pays a man into this. Arithmetic, and a good pass to hold.\n\nNow show me work, or take the road back down. I have caravans to count."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_042", "Word From The Pass"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_043", "The Varnovapol road thins out past the second bend. {CULTURE_STU} wool-trains been running with four spears instead of eight — the boyar there lost men to the snow-fever and hasn't hired fresh. I held a pass alone against three caravans once. Four spears is not a guard. Four spears is a count of mouths to shut.\n\nThere's a thane east of <span style=\"BandItPlus.Place\">Revyl</span> buying quiet. Won't say the name on open road. He takes the southern stock — {CULTURE_VLA}, {CULTURE_BAT}, anything that doesn't speak the tongue of his hall. Pays in old silver, the kind nobody asks about. I move two bodies a month his way and the ledger stays clean.\n\nA man calling himself Yarko works the Omor cut. Calls himself a trader. He's a fence with bad chains and worse prices. If you come down through the high pines, don't sell to him — he marks his stock with a brand on the wrist and the buyers know it and they pay him less for the trouble. Cleaner to bring them to me.\n\nWord is the prince's tax-rider rides north of Sibir next moon with a thin escort. Two retainers, a clerk, a strongbox. Strongbox is the smallest of the three. The clerk is the one worth chains — clerks read, and a reading man brings double in the southern markets where they need ledger-keepers and don't ask why his hands are scarred.\n\nI sell men because beasts are cheaper. That's still true. But the price on a {CULTURE_STU} smith just climbed a third since the empire started forging again, and the passes are full of smiths walking home from work they no longer have. Bring me one with strong wrists and we both eat well this winter."),
                T1HeroPool = new[] { "wanderer_sturgian_2", "wanderer_sturgian_5" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_044", "Helka Ridge-Walker"), CharacterTemplateId = "mountain_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_045", "Climbed out of a cliffside oubliette barefoot in snow.") },
                TroopT1 = new[] { "mountain_bandit" }, TroopT2 = new[] { "mountain_bandit_raider" }, TroopT3 = new[] { "mountain_bandit_chief" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_046}Three {CULTURE_STU}s dead in the passes. Six prisoners. Off you go.", "{=bp_slaverprofiles_047}Volk slides a bag of coin across.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 3, Description = "Slay 3 {CULTURE_STU} lords" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_048}Marked {CULTURE_STU} lord. Alive. Five more dead. Twenty fur for the slings.", "{=bp_slaverprofiles_049}Volk smirks.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_STU} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 5, Description = "Slay 5 {CULTURE_STU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "fur", Count = 20, Description = "Gather 20 fur" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_050}Twelve dead. Fifteen alive. The lord. Fifty fur.", "{=bp_slaverprofiles_051}Volk uncovers the deeper hold.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 12, Description = "Slay 12 {CULTURE_STU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_STU} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "fur", Count = 50, Description = "Gather 50 fur" }),
            },

            ["steppe_bandits"] = new SlaverProfile
            {
                CultureId = "steppe_bandits", Name = BandItPlus.Localization.Get("bp_slaverprofiles_052", "Bayan the Iron-Reins"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_053", "Caravan-Cutter"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_054", "Was a {CULTURE_KHU} horse-boy who watched his lord burn his village for grazing-land. Sells {CULTURE_KHU}s now."),
                GateSpeech = "{=bp_slaverprofiles_055}Chief brought you here. Good. Ride hard, kill clean, bring what I ask. We talk.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_056", "There is no cellar — only a yurt pitched apart from the others, ringed with iron stakes. Inside, six prisoners tied wrist to wrist in a circle, the way wolves hobble their kills. A {CULTURE_KHU} noble's wife refuses to meet your eyes; her wedding-braids have been cut off and lie in a pile by the door. Bayan watches her watch the floor, and says nothing."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_057", "The Iron-Reins' Ledger"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_058", "You ask what pays a man into the trade. Look at my hands. They were a horse-boy's hands once, soft on the bridle, hard on nothing. I brushed my lord's geldings before sunrise and slept in the straw with them after. That was a life. It was someone else's life.\n\nThe grass at our village ran thin one summer and my lord wanted it for his herds. He came down the slope with twelve riders and a torch. I watched my mother go into the smoke from behind a watering-trough. I watched my father go in after her. The lord saw me crouched there and rode past without a word — a horse-boy is not worth the turn of a head. That was the lesson. A {CULTURE_KHU} noble will burn you for grass and not remember your face by supper.\n\nSo I learned the reins he taught me and turned them. Every {CULTURE_KHU} caravan that crosses the steppe rim, every drover with a fat purse and a lord's seal on his belt — I cut them off the road and put them in the line. I sell them south, I sell them east, I sell them to anyone whose coin doesn't smell like home. The ones with noble cousins fetch best. I keep a ledger of their clan-marks and I have not forgotten a single one.\n\nThis is not vengeance. Vengeance is for men who think the ledger closes. Mine does not close. Every chain I lock around a {CULTURE_KHU} neck is grass paid back, one blade at a time. The trade pays well because the steppe is wide and the lords are many, and a man with iron reins can ride a long way before he runs out of throats to bind.\n\nYou came here for coin and a chief's nod. Good. Bring me {CULTURE_KHU}s — drovers, scouts, the soft-handed sons of the men who ride under banners — and we will talk longer. Bring me anything else and you waste my straw."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_059", "What Bayan Hears on the Wind"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_060", "The trade-road south of <span style=\"BandItPlus.Place\">Makeb</span> runs fat this moon. {CULTURE_KHU} remount-strings move from the summer pasture to the winter camp, and the noyan who owns them sends only four lancers ahead, four behind. Four and four. I counted them myself from the long grass. A horse-boy learns to count men the way other boys learn to count stars, and I learned young.\n\n<span style=\"BandItPlus.Name\">Lord Mesui</span> rides drunk again. His own household whispers it at the well in Aksumel — two of his sons dead in the eastern raids, and now he drinks koumiss till noon before he mounts. His column drifts in single file along the river-bend. A man who cannot keep his line cannot keep his throat. Take him on the bend, take his retinue for the block.\n\nThe buyers shift. Ortysia has gone shy — too many imperial eyes since the new garrison — but <span style=\"BandItPlus.Place\">Quyaz</span> takes anything with a pulse and asks no name. Their pit-master pays in old <span style=\"BandItPlus.Coin\">denars</span>, clipped, but he pays the day you ride in. There is also a {CULTURE_STU} factor working out of a cellar in <span style=\"BandItPlus.Place\">Revyl</span> who buys {CULTURE_KHU} women only, no men, no children. I do not ask what he does with them. The ledger does not ask either.\n\nWord from the rim: a {CULTURE_VLA} called Halgar runs a cage in the western foothills and undercuts the rest of us by a third. Let him. His stock comes off the caravan-roads, soft hands, soft feet. Mine comes off the steppe. Different meat, different table. The {CULTURE_ASE} out of <span style=\"BandItPlus.Place\">Quyaz</span> pays steppe-price for steppe-flesh, and Halgar's western chain does not reach this far.\n\nOne last thing, and hear me. A merchant caravan rode out of Chaikand three days back, light guard, heavy axles. Heavy axles mean coin, not grain. The driver is a cousin of the khan's tax-man, which means a ransom on top of the trade. Ride hard, kill the outriders clean, bring the cousin breathing. The rest you may sell or bury — I do not care which, only that the ledger closes."),
                T1HeroPool = new[] { "wanderer_khuzait_2", "wanderer_khuzait_5" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_061", "Tarsa Blood-Mare"), CharacterTemplateId = "steppe_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_062", "Rode a stolen {CULTURE_KHU} warhorse across two kingdoms to escape a lord she would not marry.") },
                TroopT1 = new[] { "steppe_bandit" }, TroopT2 = new[] { "mounted_bandit" }, TroopT3 = new[] { "mounted_bandit" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_063}Three {CULTURE_KHU} horsemen down. Six prisoners. Plain work.", "{=bp_slaverprofiles_064}Bayan tosses the purse.", 2000,
