            ["sea_raiders"] = new SlaverProfile
            {
                CultureId = "sea_raiders", Name = BandItPlus.Localization.Get("bp_slaverprofiles_069", "Hjalti Salt-Spine"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_070", "Long-Boatswain"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_071", "Pulled an oar on three different crews. Started a fourth. Sells whoever crawls out of the surf."),
                GateSpeech = "{=bp_slaverprofiles_072}Salt in your beard yet? Ha. Show me you can pull weight.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_073", "Hjalti's cellar is the bilge of a beached longship dragged up the strand. The hold smells of pitch and brine and human waste. Eight men chained to the keel-beam, all in stages of seasickness even on dry land. \"Sea breaks them faster than chains,\" Hjalti says. \"By the time the ship sells, they're glad to go anywhere with a floor that doesn't move.\""),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_074", "What the Long-Boatswain Says"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_075", "Three crews I pulled oar for before I was the one holding the rope. First crew, I was twelve, and the boatswain broke my nose for missing stroke. Second crew, the captain drowned a {CULTURE_STU} boy off the gunwale because the boy wept too loud. Third crew, I learned the trick of it — that a man pulling oar and a man in chains pull the same wood, only one of them gets paid in herring and the other in salt water up his nose.\n\nSo I started the fourth crew myself. Bought the keel from a widow in <span style=\"BandItPlus.Place\">Rivacheg</span> who didn't ask where her husband went. Half my first take was {CULTURE_STU} fisher-boys, the other half was a Vaegir caravan that thought the coast road was safe in spring. The ledger keeps no opinion. The ledger only keeps weight.\n\nWhat pays a man into this trade. I'll tell you. The sea pays nothing — she takes. Raiding pays for one winter and a funeral. But the chain pays twice. Once when you put it on him, once when you take it off in a market square and somebody hands you silver for the trouble. Twice the work of an oar, and you stand dry.\n\nI sell whoever crawls out of the surf. Doesn't matter the cloak. {CULTURE_STU}, {CULTURE_BAT}, your cousin if your cousin is wet and breathing. The surf is honest — she sorts the strong from the weak before I ever lay a hand. I just wait on the beach with the rope and the count.\n\nYou asked what pays a man in. Nothing pays you in. You wake up one morning at the oar and you understand the rope is in someone's hand, and it might as well be yours. Salt in your beard yet? Then you already know."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_076", "What Hjalti Hears on the Tide"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_077", "{CULTURE_STU} coast road past <span style=\"BandItPlus.Place\">Revyl</span> is fat this season. The thaw came late and the fur-trains piled up at the crossings — twelve, fifteen wagons strung out with six guards apiece, and half those guards are drunk Vaegir boys hired in haste. I pulled a man off one such caravan last moon. Got eighty <span style=\"BandItPlus.Coin\">denars</span> for him in Omor by sundown. No questions, no ledger. The buyer keeps a back door that opens onto the river.\n\n<span style=\"BandItPlus.Name\">Lord Bakar</span>'s levy is south chasing a {CULTURE_KHU} raid that isn't there anymore. His northern villages stand thin — old men, fish-wives, the priest. I won't touch the priest. The rest go in the hold and nobody in <span style=\"BandItPlus.Place\">Revyl</span> counts the missing till the ice breaks again. A crew out of Tyal works that same stretch — Yngvarr Cold-Tongue, calls himself a captain now. He pays in salt and short weight. Steer wide of him or split your take before you sail with him, not after.\n\nThe discreet buyers this month: a factor in Varnovapol who buys strong backs only, no women, no children, pays in {CULTURE_EMP} silver and asks if they can read. Don't lie to him; he checks. There's a quiet house in <span style=\"BandItPlus.Place\">Pravend</span> too, behind the tanner's yard — they take any flesh that breathes but they shave the price hard, claim the Empire's edicts have them nervous. Edicts. Ha. Coin still moves. It just moves slower and through more hands.\n\nWord from the gulls is that a {CULTURE_VLA} merchant convoy is putting in at Omor before the equinox — eight wagons, mercenary escort, fat with wool and a paymaster's strongbox. The escort captain is one Sir Roland, drinks too much and posts his sentries by the fire instead of away from it. I'd not take the wagons. I'd take the camp-followers and the boy who tends the horses. Less noise, same coin by the second town.\n\nLast thing. A {CULTURE_BAT} woman has been asking after me by name in Sibir. Sister to a man I sold three winters back, or wife, the messenger wasn't sure. I'd care more if she had coin. She doesn't. Tell her, if she finds your fire, that Hjalti is at sea and the sea keeps its ledger sealed."),
                T1HeroPool = new[] { "wanderer_sturgian_3", "wanderer_sturgian_6" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_078", "Inga Wave-Cutter"), CharacterTemplateId = "sea_raider", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_079", "Swam ashore from a wreck wearing a dead jarl's mail; kept it.") },
                TroopT1 = new[] { "sea_raider" }, TroopT2 = new[] { "sea_raider_warrior" }, TroopT3 = new[] { "sea_raider_chief" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_080}Three {CULTURE_STU} coast-lords. Six prisoners. Start there.", "{=bp_slaverprofiles_081}Hjalti spits and pays.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 3, Description = "Slay 3 {CULTURE_STU}s" },
