                QuestT2 = NewQuest("{=bp_slaverprofiles_082}{CULTURE_STU} lord alive. Five dead. Twenty fur for the slaver-hold.", "{=bp_slaverprofiles_083}Hjalti grins through bad teeth.", 5000,
