                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "fur", Count = 20, Description = "Gather 20 fur" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_084}Twelve dead. Fifteen alive. The lord. Fifty fur. After that — we sail.", "{=bp_slaverprofiles_085}Hjalti claps your shoulder hard.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 12, Description = "Slay 12 {CULTURE_STU}s" },
