            ["desert_bandits"] = new SlaverProfile
            {
                CultureId = "desert_bandits", Name = BandItPlus.Localization.Get("bp_slaverprofiles_086", "Yusuf the Salt-Counter"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_087", "Caravan-Reaver"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_088", "Was sold once at the {CULTURE_ASE} pole-block at thirteen. Bought himself back by twenty-five. Counts every coin."),
                GateSpeech = "{=bp_slaverprofiles_089}The chief's word carries weight — for him. Make yours worth something to me.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_090", "Yusuf's cellar is dug deep beneath the sand to keep the noon-heat out. The prisoners squat against the cool clay walls and rarely look up. He passes a waterskin around himself — \"They sell for more if they don't dry,\" he explains. The far wall has a wooden post worn smooth by chained wrists. Yusuf touches it absently as he walks past. He doesn't say why."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_091", "What the Salt Taught Me"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_092", "Thirteen. That was the price they wrote beside my name on the {CULTURE_ASE} pole-block. Not my age — the silver. A trader from <span style=\"BandItPlus.Place\">Quyaz</span> paid it without looking at my face. He looked at my teeth, my wrists, the length of my stride. The man who sold me was my uncle. He counted the coins twice before he walked away, and he never once turned his head.\n\nI stood on that block four hours in the salt-wind. Salt gets into the rope-burns and stays there. Years later, when a buyer haggles me down a dinar, I still feel it — that small white sting along the wrist, telling me what a man is worth when nobody speaks for him. So I learned to speak for myself. I learned to count. Every coin that crossed my palm I marked, and every coin I owed I marked twice.\n\nTwelve years it took. Twelve years of caravan work, of knife-work, of sitting at the fires of men who did not know my name and were better for it. At twenty-five I walked back to the same pole-block with a purse heavy enough to buy three of me, and I bought one. Myself. The clerk did not remember the boy. He wrote the sum down, took his cut, and asked if I wanted the receipt. I keep it folded in my belt to this day.\n\nAfter that, the trade was the only thing that made sense. A man who has been counted does not forget the counting. I do not hate the chains — chains are honest. The dinar is honest. What I hate is the uncle who looks away while the silver changes hands, and that one I cannot sell, because he is already in the desert somewhere, dead of his own thirst, I hope.\n\nSo you ask what pays a man into this trade. I will tell you plain. The trade paid me back what was taken, dinar for dinar, and then it paid me a little more, and a man who has been counted will keep counting until the ledger runs out. Bring me a captive worth weighing, and we will talk. Bring me your purse light, and we will not."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_093", "What Yusuf Counts"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_094", "The road from <span style=\"BandItPlus.Place\">Quyaz</span> to Iqbayl runs thin this moon. {CULTURE_ASE} caravans cut their guards from twelve spears to eight — the sultan's levy ate the rest, and the merchants pray to their stars instead. Stars don't stop a curved blade in dune-shadow. I take the third night out of the well at Bahyat; that's when the camel-drivers sleep heaviest and the moon is small.\n\nThere's a buyer in <span style=\"BandItPlus.Place\">Sanala</span> wears clean linen and asks no names. Pays in silver, not gold — counts every coin twice before he lets you touch the purse. I like him. He took four girls off me last new-moon at forty-two <span style=\"BandItPlus.Coin\">dinars</span> the head, and the ledger closed clean. Word is he ships them west by sea, but I don't ask. A man who asks too much gets sold cheap.\n\n<span style=\"BandItPlus.Name\">Lord Unqid</span> lost his second son to fever and three caravans to bandits in the same season, and his banner-men haven't been paid since the spring rains. His escorts walk slow now, look at the sand more than the horizon. A column of his moves through the Hubyar pass next dark moon. Twenty wagons. Six guards. You do the counting.\n\nWatch for a man called Khuzaim — calls himself a salt-trader, but he moves flesh out of Durrin by the back gate and pays his runners in promises. Two of mine went to him last winter and came back with nothing but bruises and a story. I do not deal with him now. If you see his caravan on the south track, take it. He won't report the loss; he can't.\n\nThe {CULTURE_VLA} caravan-masters are the soft mark this season — they march through our sand like it's their father's pasture, and their sergeants drink at noon. One of them I sold at thirteen to the pole-block where I stood, and I remember his face. The desert keeps its ledger. I keep mine."),
                T1HeroPool = new[] { "wanderer_aserai_2", "wanderer_aserai_5" },
                T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_095", "Layla Sand-Sworn"), CharacterTemplateId = "desert_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_096", "Walked seven days through the deep desert wearing only a stolen merchant's robe.") },
                TroopT1 = new[] { "desert_bandit" }, TroopT2 = new[] { "desert_bandit_rider" }, TroopT3 = new[] { "desert_bandit_chief" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_097}Three {CULTURE_ASE} dead. Six prisoners. The desert teaches you.", "{=bp_slaverprofiles_098}Yusuf weighs your purse, smiles.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 3, Description = "Slay 3 {CULTURE_ASE}" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_099}{CULTURE_ASE} lord — alive. Five dead. Twenty salt for the brine-jars.", "{=bp_slaverprofiles_100}Yusuf nods slowly.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_ASE} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 5, Description = "Slay 5 {CULTURE_ASE}" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "salt", Count = 20, Description = "Gather 20 salt" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_101}Twelve dead, fifteen alive, the lord. Fifty salt.", "{=bp_slaverprofiles_102}Yusuf draws back a curtain.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 12, Description = "Slay 12 {CULTURE_ASE}" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_ASE} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
