            ["bp_frost_reavers"] = new SlaverProfile
            {
                CultureId = "bp_frost_reavers", Name = BandItPlus.Localization.Get("bp_slaverprofiles_103", "Brand the Frostbitten"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_104", "Ice-Master"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_105", "Lost three fingers to a thrall-chain in a {CULTURE_STU} winter and never warmed since."),
                GateSpeech = "{=bp_slaverprofiles_106}Chief warmed to you, did he? Cold doesn't. Prove yourself.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_107", "The cellar is a half-frozen ice-house, prisoners packed in straw so their breath doesn't waste heat. Brand walks among them counting fingers — \"Lose two, price drops. Lose four, they go to the dogs.\" One of the prisoners, a {CULTURE_STU} boy of maybe sixteen, watches him with the dead calm of someone who has already stopped being a person."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_108", "What the Cold Bought"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_109", "Three fingers. That's what the chain took from me, that first winter. I was fourteen, thrall-bound, and the iron froze to the bone before the {CULTURE_STU} master noticed his stock was rotting on the line. He cut them off himself, on a stump outside the longhouse, and threw them to the dogs. I watched the dogs eat my fingers in the snow. That's when the cold got in, and it's never gone out.\n\nI worked the chain six more winters before I broke it. Killed the master with the same knife he'd carved me with. Walked north until the trees gave up. You ask what pays a man into this trade — I'll tell you. It wasn't coin. It was the ledger. Every {CULTURE_STU} throat I open now is a finger paid back. I'm not done counting.\n\nThe reavers found me half-dead on the ice, and they knew what I was the moment they saw the stumps. A man who's been on the line knows the line. I can read a thrall's price in his shoulders before he opens his mouth. I know which ones break in a week and which ones go three seasons. The buyers down south pay me well for that knowing.\n\nSometimes a young one asks me if I hate them — the {CULTURE_STU}s, the chained ones, the buyers who fondle the wrists before they pay. I tell him no. Hate warms a man. I haven't been warm since the dogs ate my fingers. This is just the work. Chain, mark, coin, next. The cold does the rest.\n\nSo when you ask what brought me here, friend, look at my hand. Two fingers gone on the left, one on the right. Each one bought by a {CULTURE_STU}, and each one I'm collecting back. Slow trade. Patient trade. The ledger keeps."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_110", "What Brand Hears on the Ice-Road"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_111", "The road north of <span style=\"BandItPlus.Place\">Varcheg</span> runs thin this season. {CULTURE_STU} patrols have pulled inward to guard the Lord's hall, and the trade-track between two villages I won't name carries grain wagons with four guards where last winter it had ten. A man with cold hands and a quiet bow can take the drivers and leave the oxen — the oxen draw too much eye. I took six off that road already. Six pairs of hands that don't know the word for warm.\n\n<span style=\"BandItPlus.Name\">Lord Bratomir</span> lies abed with a wound that won't close. His housecarls drink in the longhouse and his daughter rides the timber roads with a sworn-sword and two girls. I won't say more on that. A man with my fingers does not boast before the take. But the ledger remembers, and someone will write that line before the thaw.\n\nWord from a tanner in <span style=\"BandItPlus.Place\">Revyl</span> — there's a buyer behind the back gate who pays in southern silver for women who can sew and men who can split wood. No questions on the mark. He sends his factor out at second moon, never the same alley. I sold him two last month. He pays slow but he pays, and he doesn't squint at the brand the way the legal markets do.\n\nA {CULTURE_BAT} crew works the western passes now. Calls himself Cuirig or some such — buys cheap, drives hard, loses one in three to the cold. Amateur. He'll cross my road before midwinter and we'll have a conversation about who pulls thralls out of MY snow. The Empire caravans coming up from <span style=\"BandItPlus.Place\">Pravend</span> run heavier guard than they did, but their scouts are southern boys. They don't know how the wind moves before a storm. Three of them froze last week and I took the fourth in chains while he was still warm enough to walk.\n\nLast — there's an {CULTURE_ASE} factor wintering at a hidden port east of here. He buys strong backs by the lot of ten, ships them south before the ice breaks. Pays in coin you can spend anywhere. I'm moving my winter stock to him before the moon turns. If you've a thrall worth more than his ration of bread, bring him while the price still climbs."),
                T1HeroPool = new[] { "wanderer_sturgian_2" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_112", "Gerd Iron-Skirt"), CharacterTemplateId = "sea_raider", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_113", "Killed a jarl with a fish-knife and lived to laugh.") },
                TroopT1 = new[] { "sea_raider" }, TroopT2 = new[] { "sea_raider_warrior" }, TroopT3 = new[] { "sea_raider_chief" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_114}Three {CULTURE_STU}s. Six prisoners.", "{=bp_slaverprofiles_115}Brand pays in cold silver.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "sturgia", Count = 3, Description = "Slay 3 {CULTURE_STU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_116}{CULTURE_STU} lord alive. Five dead. Twenty fur.", "{=bp_slaverprofiles_117}Brand offers a drink.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_STU} ALIVE" },
