            ["bp_marsh_stalkers"] = new SlaverProfile
            {
                CultureId = "bp_marsh_stalkers", Name = BandItPlus.Localization.Get("bp_slaverprofiles_120", "Wenna of the Reeds"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_121", "Mire-Mistress"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_122", "Drowned her first owner in three feet of standing water. Never cared for dry land since."),
                GateSpeech = "{=bp_slaverprofiles_123}Mud doesn't lie. Bring me proof you can wade through it.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_124", "Wenna's cellar is half-flooded — a marsh seeping up from below, knee-deep in places. Prisoners stand on raised platforms of bound reeds, ankles always wet. She walks barefoot through the water without flinching. \"Mud takes the fight out of them faster than chains,\" she says. The deepest pool has something at the bottom that Wenna doesn't talk about and the prisoners don't look at."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_125", "What The Mire Taught Wenna"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_126", "My first owner thought standing water was safe. He'd wade in up to his shins to check the eel traps, and he'd laugh at me for keeping to the reeds. One dusk I walked behind him with the chain he'd put round my throat that morning, and I looped it once round his neck, and I sat on his shoulders till the bubbles stopped. Three feet of brown water. Not enough to drown a dog. Enough for him.\n\nI left him there for the leeches and walked out wearing his coat. The chain I kept. It hangs by my hip still — same iron, same weight. I learned that day the mire takes what's owed it without asking twice, and a man who can't read the water is already a corpse that hasn't lain down.\n\nThe trade found me after. {CULTURE_BAT} raiders came through the fen looking for tin and went home in my coffles instead, because they didn't know which tussock would hold them and which was a green lid over six feet of black. I sold the first three to a {CULTURE_STU} factor for forty <span style=\"BandItPlus.Coin\">denars</span> and a salt block. Forty <span style=\"BandItPlus.Coin\">denars</span> buys a lot of rope. Rope buys more men.\n\nDry-land slavers haggle over teeth and shoulders. I haggle over lungs. A {CULTURE_BAT} who's spent a night chained to a stake with the tide rising will walk quiet to any buyer you put him in front of — the mud has done my breaking for me. That's what pays a man into this trade, friend. Finding the one thing the world gave you for free, and learning to sell it.\n\nYou asked plain so I answered plain. Now show me you can stand where I stand without sinking, or take your boots back to the road."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_127", "What Wenna Hears in the Reeds"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_128", "The fen-roads carry word, same as the dry ones. Travellers stop at my reed-huts because the causeway floods twice a moon, and a wet man trades cheap. I sit at the table, I pour the mud-beer, and I listen. They forget the woman in the corner is the one who'll measure their wrists by sundown.\n\nThere's a {CULTURE_BAT} thane two valleys north — Mabrigh, calls himself a lord — who's been bleeding levies into a feud with his own cousin. His western paths run with three guards now, four on a feast day. A caravan came through last week carrying his cousin's salt-tribute, and I marked the wheel-ruts. Light load, heavy fear. Someone with twenty bows could take it without raising a voice. I'd take it myself, but I prefer the goods that walk and breathe.\n\nThe town of Llyngarth is buying quiet. Their reeve sent a man down to the fen-edge in plain wool, and he asked me about strong backs — no tattoos, no missing teeth, mouths that won't shout at market. He paid in good silver and bad lies. Their forge has more orders than free hands, and the guildmasters don't want it written in any ledger. I've sent three already. They'll take more.\n\nWord is a {CULTURE_STU} called Yarvik is working the upper marshes, undercutting on women. He pays in furs, which means he's selling them east before the snow-roads close. I don't begrudge a man his trade, but he took a girl from a village I'd already marked, and a debt in the fens is paid in standing water. He'll find me, or I'll find him. The reeds keep count.\n\nThere's a {CULTURE_VLA} column moving down the old causeway toward the coast — pilgrims, they call themselves, but pilgrims don't carry strongboxes that tilt the wagon-bed. Twelve guards, all looking sideways. They'll camp at the dry stones on Frilday because there's nowhere else, and the dry stones sit in three feet of black water by the second watch. I drowned a man in three feet once. It's enough."),
                T1HeroPool = new[] { "wanderer_battanian_3" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_129", "Aerwen Black-Eel"), CharacterTemplateId = "forest_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_130", "Knew every channel between <span style=\"BandItPlus.Place\">Pravend</span> and the sea by sixteen.") },
                TroopT1 = new[] { "forest_bandit" }, TroopT2 = new[] { "forest_bandit_raider" }, TroopT3 = new[] { "forest_bandit_veteran" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_131}Three {CULTURE_BAT}s dead. Six prisoners.", "{=bp_slaverprofiles_132}Wenna counts coin in silence.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 3, Description = "Slay 3 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_133}{CULTURE_BAT} lord alive. Five dead. Twenty hardwood.", "{=bp_slaverprofiles_134}Wenna gives a small smile.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_BAT} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 5, Description = "Slay 5 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 20, Description = "Gather 20 hardwood" }),
