                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 12, Description = "Slay 12 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_BAT} ALIVE" },
