            ["bp_highwaymen"] = new SlaverProfile
            {
                CultureId = "bp_highwaymen", Name = BandItPlus.Localization.Get("bp_slaverprofiles_137", "Ardvad the Buckle-Cutter"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_138", "Toll-Reeve"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_139", "Was a noble's son who stopped one too many caravans on his way to feast."),
                GateSpeech = "{=bp_slaverprofiles_140}{CULTURE_VLA} roads pay well. Bring me {CULTURE_VLA}s and we'll talk.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_141", "Ardvad's cellar is a converted wine-cave; the casks are gone, the iron-bound oak doors remain. He keeps his prisoners in proper cells with proper locks and proper beds — \"My father raised me a gentleman,\" he says without irony. A {CULTURE_VLA} knight's son glares at him through the bars. Ardvad bows mockingly and moves on."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_142", "The Toll-Reeve's Answer"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_143", "My father kept a hall on the western road. Good wine, good plate, a buckle of {CULTURE_VLA} silver at every belt that crossed his threshold. I rode out on a feast-day to meet the cousins coming up from <span style=\"BandItPlus.Place\">Galend</span>. I came back two days later with their purses and none of their company.\n\nThe first caravan was a lark. The second a debt. By the third my hands knew the work better than they knew a wine-cup, and my father knew my face on a hue-and-cry parchment before he knew my voice at table. He paid the reeve to look the other way once. Twice. The third time he sent a man to the road to tell me not to come home. That man wore good boots. I kept them.\n\nWhat pays a man into this trade? Habit, mostly. A noble's son learns to take what passes him. The road taught me the rest — that a {CULTURE_VLA} merchant kneels the same as a {CULTURE_VLA} sergeant, that the silver weighs the same whether you cut it from a belt or buy it clean. I cut buckles for years before I understood the body inside the belt was worth more than the belt. Slow lesson. Expensive teacher.\n\nNow I sit at a toll-post my father would have hanged me for keeping. The road that fed him feeds me. The cousins I robbed have grandsons riding it, and I do not know their faces and they do not know mine, and we settle the ledger between us in chains. There is a justice in it I do not look at too closely.\n\nBring me {CULTURE_VLA}s. I will pay you in the coin my father refused me. That is the whole of the trade and the whole of the answer."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_144", "What Ardvad Hears at the Toll"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_145", "The road between Sargot and Jaculan is fat this season. Three caravans came through in a fortnight, all with thin guard — two crossbows and a drunk sergeant, the kind of escort a merchant buys to feel brave. The buckles I cut off the last sergeant's belt are still on my table. He bled out asking for his wife's name back.\n\n<span style=\"BandItPlus.Name\">Lord Caelin</span> of the Western March rides with six men now, not twelve. His coffers thinned after the harvest tax went bad, and he won't pay for proper retinue till spring. A man who knows the timber-road past Charas told me Caelin's daughter travels to her aunt's hall on the new moon — light escort, covered wagon. I have not decided yet whether she is worth the noise. {CULTURE_VLA} noble girls fetch coin in three ports, but they also draw banners.\n\nThe salt-buyer in <span style=\"BandItPlus.Place\">Pen Cannoc</span> takes flesh now. Quiet about it, ledgers it as \"labor stock,\" moves them down the coast to the galleys. He pays less than the desert routes but he pays in clipped <span style=\"BandItPlus.Coin\">denars</span> and asks no questions about the brand. I send him my {CULTURE_VLA} field-hands and keep the noble-blood for the slower buyers who count teeth and pedigree.\n\nA man calling himself Hardric works the <span style=\"BandItPlus.Place\">Galend</span> crossing two days east of me. Cuts throats where I cut buckles — sloppy, leaves bodies on the verge, draws the militia. I sent him word once that his corpses were ruining my toll. He sent back a finger in a cloth. We have an understanding now: he keeps east of the millstream, I keep west, and neither of us lifts the other's marks.\n\nThere is talk the {CULTURE_VLA} king is raising a road-patrol come the thaw. Two hundred horse, sworn to clear the highways. I lived in a hall like his once. I know how long such patrols last when the wine runs and the lords get bored. I am buying chain and hiring two more bows before the snow lifts — when the patrol rides out and gets tired, the merchants will come through thinking the road is safe. That is when the ledger fills."),
                T1HeroPool = new[] { "wanderer_vlandian_2", "wanderer_vlandian_5" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_146", "Tessa of Eastdown"), CharacterTemplateId = "looter", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_147", "Took a horse and a sword from her own father at fifteen and ran.") },
                TroopT1 = new[] { "looter" }, TroopT2 = new[] { "mounted_bandit" }, TroopT3 = new[] { "mounted_bandit" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_148}Three {CULTURE_VLA}s dead. Six prisoners.", "{=bp_slaverprofiles_149}Ardvad pays in clipped coins.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "vlandia", Count = 3, Description = "Slay 3 {CULTURE_VLA}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_150}{CULTURE_VLA} lord alive. Five dead. Twenty grain.", "{=bp_slaverprofiles_151}Ardvad nods.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_VLA} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "vlandia", Count = 5, Description = "Slay 5 {CULTURE_VLA}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "grain", Count = 20, Description = "Gather 20 grain" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_152}Twelve dead, fifteen alive, the lord, fifty grain.", "{=bp_slaverprofiles_153}Ardvad opens a strongbox.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "vlandia", Count = 12, Description = "Slay 12 {CULTURE_VLA}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_VLA} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
