            ["bp_slaver_caravans"] = new SlaverProfile
            {
                CultureId = "bp_slaver_caravans", Name = BandItPlus.Localization.Get("bp_slaverprofiles_154", "Tahir Pole-Master"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_155", "Block-Captain"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_156", "Runs the longest slaver chain south of the {CULTURE_ASE} pole-blocks. Sells whoever the desert hands over."),
                GateSpeech = "{=bp_slaverprofiles_157}Chief vouches for you. Sand doesn't. Let's see what the dunes give back.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_158", "The caravan-master keeps no cellar — only the long line of yoked walking-chains that snake from one camel-train to the next. At rest, the prisoners squat in the shade of stacked goods. Tahir walks the line counting heads, marking a wax tablet. He is the only slaver in your acquaintance who keeps written records, and that is, somehow, the worst part."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_159", "What Tahir Tells At The Pole"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_160", "The sand pays. That's the whole of it. I came south as a caravan-boy with two coppers and a waterskin half-empty, and the dunes taught me fast — out here a man is worth what the next buyer says he's worth, and not a grain more. I watched my first master die of thirst three days off the pole-blocks. I took his rope. I took his line. The {CULTURE_ASE} he was driving I sold at the next well-camp before his body cooled.\n\nThe pole-blocks gave me my name. Forty stations between the salt-pans and the southern markets, each one a post hammered into rock, each post a place to chain a man while you count him. I learned the count early — wrist, throat, ankle, tongue. A buyer wants to see the tongue most of all. A mute fetches half. I run the longest chain south of the {CULTURE_ASE} blocks now because I never lost a count, and the desert respects a man who can still tell forty from thirty-nine after a sandstorm.\n\nYou ask what pays a man into this. Hunger pays first. Then habit. Then the ledger — and the ledger is the worst of them, because once your name is in the southern books as a man who delivers, the dunes will keep handing you bodies whether you want them or not. Runaways. Debt-broke caravan guards. Whole villages the raiders couldn't be bothered to keep. The sand gives them up, I move them along. That's the trade.\n\nI don't sell my own. The {CULTURE_ASE} I kill or chain, that's the line — they bled my first master's caravan, so they pay the toll forever. Everyone else, I weigh. Hessa down in the well-camp reads bones for me when the count gets thin; she told me once I'd die owing the desert more than it owes me. Maybe so. The ledger runs both ways out here, and the sand keeps better books than I do.\n\nSo you stand at my pole and ask the question men ask before they sign on. I'll tell you plain. There's no calling in it. There's no story worth the breath. A boy with empty hands took a dead man's rope, and the rope never let go. The chief vouches for you. The sand doesn't. Keep your count and keep your tongue, and we'll see what the dunes give back."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_161", "What Tahir Hears on the Sand"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_162", "The south sand-routes are paying again. Two {CULTURE_ASE} grain caravans crossed my chain last moon with six guards apiece — six, where they used to ride twelve. The drought thinned their coffers, and thin coffers mean thin spears. I marked the routes in my ledger; the next wagon that runs that lean, I take whole.\n\nA {CULTURE_VLA} factor in <span style=\"BandItPlus.Place\">Quyaz</span> has been buying quiet. He won't say it at the block, but his man comes after dusk and pays in clipped <span style=\"BandItPlus.Coin\">denars</span> for women who can stitch. Three I sold him last week, no questions on where they came from. The dunes gave them back; he asked only how strong their hands were.\n\nWord on the pole is that the Banu Hilal lost a sheikh's cousin to a raid south of the salt pans, and the clan's grown soft on grudges — they ride out half-strength now, two days behind any column they chase. A man who knows the wadis could lift a string of their herders and be back in his cups before the dust settled. I'm not that man this season. The chief wants flesh, not feud.\n\nOld Ramun out of the western chain is dying or close to it. His block-boys haven't been paid in a month and two of his outriders drifted over to me asking for line-work. I took one — the other had a slack hand on the lead, and a slack hand loses you stock. When Ramun goes, his routes go cheap, and I mean to be the first at his ledger.\n\nThe desert hands over what it hands over. I keep my chains oiled and my eyes on the southern wells, because thirst makes a free man cheaper than any auction ever did."),
                T1HeroPool = new[] { "wanderer_aserai_2" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_163", "Selma Veiled-Knife"), CharacterTemplateId = "desert_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_164", "Was a merchant's wife who slit his throat and stole his caravan.") },
                TroopT1 = new[] { "desert_bandit" }, TroopT2 = new[] { "desert_bandit_rider" }, TroopT3 = new[] { "desert_bandit_chief" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_165}Three {CULTURE_ASE} dead. Six prisoners.", "{=bp_slaverprofiles_166}Tahir grunts approval.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 3, Description = "Slay 3 {CULTURE_ASE}" },
