                QuestT2 = NewQuest("{=bp_slaverprofiles_167}{CULTURE_ASE} lord alive. Five dead. Twenty dates.", "{=bp_slaverprofiles_168}Tahir pays.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_ASE} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 5, Description = "Slay 5 {CULTURE_ASE}" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "date_fruit", Count = 20, Description = "Gather 20 date fruit" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_169}Twelve dead, fifteen alive, the lord, fifty dates.", "{=bp_slaverprofiles_170}Tahir opens the deepest tent.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "aserai", Count = 12, Description = "Slay 12 {CULTURE_ASE}" },
