            ["bp_fallen_legionaries"] = new SlaverProfile
            {
                CultureId = "bp_fallen_legionaries", Name = BandItPlus.Localization.Get("bp_slaverprofiles_171", "Decimus the Cashiered"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_172", "Branded-Centurion"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_173", "Lost his commission for a crime he didn't deny. Brand on his cheek, two on his back. Sells imperials who once outranked him."),
                GateSpeech = "{=bp_slaverprofiles_174}Discipline still matters. Show me you've got some.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_175", "Decimus runs the cellar like a legionary holding-cell — six prisoners standing at parade rest, eyes forward, addressed by serial number rather than name. The cleanest cellar you've seen. \"{CULTURE_EMP} discipline holds both ways,\" he says without smiling. The branded centurion on his cheek twitches as he speaks. None of the prisoners look at it."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_176", "The Branded Centurion's Ledger"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_177", "You ask what pays a man into this trade. Look at my face. The brand sits there for the asking — a hot iron, held by a man who used to take my orders. They burned the eagle off my cheek and left the scar in its shape, so I would carry the legion on me even after the legion was done with me.\n\nI don't deny what they cashiered me for. I did it. Whether it was worth doing is a different ledger. The court took my sword, my pension, my name on the rolls. Two more brands on the back, for the discipline of it. Then they opened the gate and told me to walk.\n\nA branded man doesn't get hired to guard a caravan. He doesn't get a plot of land. He gets one trade, and the trade is the one I knew already — moving men in a line, counting them, feeding them just enough. The only difference now is the chain instead of the marching order, and the buyer instead of the quartermaster.\n\nI sell imperials. I sell the ones who used to stand a rank above me and look through me like I was air. Some of them I knew by name before the chains went on. I don't gloat. I weigh them, I price them, I move them on. The coin spends the same whether the neck under the iron is a farmer's or a tribune's, but I'll admit the tribune sits a little easier in the ledger.\n\nThat's what pays a man into this. Not greed, not appetite. A brand, a closed door, and the one skill the legion left him with. Discipline still matters in this work, more than people think. Show me you've got some, and we'll do business. Show me you haven't, and you'll learn what the line feels like from the inside."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_178", "What Decimus Heard on the Limes"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_179", "The cohort road out of <span style=\"BandItPlus.Place\">Amitatys</span> runs fat right now. Two pay-chests went through last week with twelve spears each, but the relief column from the south got cut to four men after the levy call. The fourth man limps. I'd not take it myself — too close to a garrison that still remembers my face — but a crew with no brand and a fast cart could break a centurion's career on that stretch in one night.\n\nThere's a magistrate in <span style=\"BandItPlus.Place\">Phycaon</span> buying quiet. He won't meet you, won't write you, won't speak your name in daylight. His steward comes to the back of a wineshop near the south gate on the third evening of the week and pays in old <span style=\"BandItPlus.Coin\">denars</span> for imperial-born only. He wants them literate. I sent him a clerk from Lageta last month — the man had cried himself hoarse before I marched him in, and the steward paid above the ledger without a word of haggle. They serve in cellars there, I think. They don't come back up.\n\nOlynia's caravan-master Kresos runs a thin guard on his copper string because he thinks his {CULTURE_ASE} paper protects him. It does not protect him from me. He moves at dusk along the old aqueduct road every seventh day and his outriders drink. There's also a {CULTURE_VLA} called Berengar working the same stretch — calls himself a free-rider, sells whoever falls. We've not spoken. If you cross him, do it on the road, not in a town; he keeps a writ from some second son in <span style=\"BandItPlus.Place\">Galend</span> and the locals pretend it means something.\n\nThe empire's own recruiters are the best customers I've had this season. A tribune at the border post outside <span style=\"BandItPlus.Place\">Pen Cannoc</span> will trade you a wagon of grain and silver for any deserter you bring him still walking — he reattaches them to a punishment cohort and pockets the bounty himself. I have brought him three. He does not ask how I knew which men to take. He looks at my cheek and writes the chit and turns away. Discipline still matters, you see. Even from his side of the line, it still matters.\n\nOne last word, and I give it for nothing. A reeve in Epicrotea is asking after me by my old name — the name on the brand, not the one I wear. If a man comes to your camp wanting to buy a single Fallen Legionary, do not ask his price. Cut him and bury him deep. I will know who did it, and I will remember."),
                T1HeroPool = new[] { "wanderer_imperial_3", "wanderer_imperial_5" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_180", "Marcia Bare-Brand"), CharacterTemplateId = "looter", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_181", "Cashiered twice from two legions and never apologized for either.") },
