            ["bp_sky_raiders"] = new SlaverProfile
            {
                CultureId = "bp_sky_raiders", Name = BandItPlus.Localization.Get("bp_slaverprofiles_188", "Bran Hawk-Eye"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_189", "Crag-Watcher"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_190", "Climbed every cliff in the {CULTURE_BAT} highlands by twenty. Sells those who couldn't."),
                GateSpeech = "{=bp_slaverprofiles_191}Highlands don't forgive softness. Neither do I.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_192", "The cellar is no cellar at all — a wind-cut ledge halfway down the cliff, with a single iron ring driven into the stone. The four prisoners are tethered along it by twelve feet of chain each, so they can sit but not sleep without falling. Below: a thousand feet of nothing. Bran watches them without expression. \"They learn fast,\" he says. \"Anyone slow learns the long way down.\""),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_193", "What the Crag Taught Me"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_194", "I climbed before I walked. By twenty I'd put my hands on every cliff between the Sea of Stars and the moors — every chimney, every overhang, every rotten ledge that pretends it'll hold a man's weight. The {CULTURE_BAT}s up there sing about their crags like the rocks owe them something. They don't. The rock owes nobody.\n\nI learned the trade by watching who fell. A man who climbs soft dies on the third pitch. A man who climbs hard sometimes lives to the fourth. The ones I bring down in chains now — I've watched them my whole life from above. Goatherds. Charcoal-burners. Painted boys playing warrior on ledges their fathers couldn't hold. I know which of them would've slipped before winter. I just took the fall out of their hands.\n\nThere was a season I tried honest work. Guided a {CULTURE_VLA} merchant's son up to the standing stones for a fee. He paid in silver and looked at me like I was a dog that had performed a trick. That same week I roped a {CULTURE_BAT} woodcutter off a goat-track and a Sky-Raider quartermaster paid me three times the silver, and looked at me like a man. The ledger does its own arithmetic. I stopped pretending I hadn't read it.\n\nNow I sit the crag and I watch. I see who's strayed from the village. I see who's bled their hunting-dog dry and gone deeper than they should. The highlands give them up to me one at a time, and I bring them down on a short rope. Some go quiet. Some go talking about their gods. The rock doesn't care which, and after twenty years up there, neither do I.\n\nYou asked what pays a man into this. Nothing pays him in. The hills push him to the edge of the trade, and one day he looks down and finds he's already standing in it. That's all. That's the whole story."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_195", "What the Crag-Watcher Hears"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_196", "The high pass above Llanruadh has a {CULTURE_BAT} convoy moving every third dawn. Six guards, two wagons, a guide who drinks. I watched them from the crag for a week before I took the last one. The cliffs do half the work — a man pinned against stone bargains faster than a man on open road.\n\n<span style=\"BandItPlus.Name\">Lord Caradros</span> of the western holds is bleeding men to a feud with his own cousin. His patrols are thin and his stewards are buying quietly — they need bodies for the quarry above Dunglanys and they don't ask where the bodies come from. Send your stock through the back gate after dark. The reeve there knows my mark and takes <span style=\"BandItPlus.Coin\">denars</span> without counting twice.\n\nThere's a {CULTURE_VLA} flesh-broker called Ostred working the lowland edge. He pays well for highland women but he's slow with coin and slower with truth. I dealt with him once. He tried to short me four heads and I left him three fingers lighter. Word is he's looking for me now. Let him look. The cliffs hide a man who wants to stay hidden.\n\nA caravan of pilgrims came through the gorge last moon — twelve souls, two old swords between them, headed for some shrine I don't remember the name of. Pilgrims walk like the road owes them safety. It doesn't. I marked their route and passed it to a brother in the lower camps for a cut. Easier than climbing.\n\nThe town of <span style=\"BandItPlus.Place\">Pen Cannoc</span> is buying again. The smith there lost his apprentices to the plague and needs hands that don't ask wages. He takes {CULTURE_BAT} boys, no questions, half the going rate but cash in fist. Move three at a time, no more — the constable counts heads when bored, and a counted head is a hanged head."),
                T1HeroPool = new[] { "wanderer_battanian_3" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_197", "Una of the Eyrie"), CharacterTemplateId = "forest_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_198", "Killed a hawk-keeper with his own gauntlet and took the bird.") },
                TroopT1 = new[] { "forest_bandit" }, TroopT2 = new[] { "forest_bandit_archer" }, TroopT3 = new[] { "forest_bandit_marksman" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_199}Three {CULTURE_BAT}s dead. Six prisoners.", "{=bp_slaverprofiles_200}Bran pays in good silver.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 3, Description = "Slay 3 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_201}{CULTURE_BAT} lord alive. Five dead. Twenty hardwood.", "{=bp_slaverprofiles_202}Bran offers a hand.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_BAT} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 5, Description = "Slay 5 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 20, Description = "Gather 20 hardwood" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_203}Twelve dead, fifteen alive, the lord, fifty hardwood.", "{=bp_slaverprofiles_204}Bran shows the cliff-cage.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "battania", Count = 12, Description = "Slay 12 {CULTURE_BAT}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_BAT} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 50, Description = BandItPlus.Localization.Get("bp_hcs_016", "Gather 50 hardwood") }),
            },

            ["bp_steppe_wolves"] = new SlaverProfile
            {
                CultureId = "bp_steppe_wolves", Name = BandItPlus.Localization.Get("bp_slaverprofiles_205", "Targud Wolf-Brother"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_206", "Pack-Leader"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_207", "Hunted {CULTURE_KHU} outriders the way wolves hunt deer — for years, in winter, with patience."),
                GateSpeech = "{=bp_slaverprofiles_208}Pack knows pack. Show me you can run with us.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_209", "Targud calls his cellar the den. It is a steep pit covered with a lattice of sharpened stakes — the prisoners can sit but cannot stand upright without bleeding. \"Wolf logic,\" he explains. \"A cornered prey doesn't fight. A bleeding prey doesn't run.\" He tosses scraps down through the lattice. The prisoners do not fight over them; they have learned what happens to those who do."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_210", "What Targud Says"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_211", "My father ran with the pack before me. He took me into the winter steppe when I was small enough to ride pillion, and he taught me how a wolf reads a track three days old. The {CULTURE_KHU} outriders came through our valley one spring and burned what they could not carry. My father did not survive that fire. I learned the rest of the trade alone, with his knife at my belt and his name in my mouth.\n\nI started with one. A scout, separated from his patrol, his horse lamed in a drift. I took him at dusk and walked him sixty miles to a coast-trader who paid in silver and asked no questions. That coin bought me my first proper bow. The second {CULTURE_KHU} bought me a second man for the pack. The trade fed itself after that, the way a wolf-line feeds itself once it learns the shape of the deer.\n\nYears of it. Winters of waiting in the wind with my breath frozen on my collar, watching a campfire for the moment a man steps away from his brothers to piss. Patience is the whole craft. The steppe rewards the patient and buries the rest. I have buried a great many.\n\nWhy do I sell them and not kill them. Coin keeps the pack fed and warm and armed, and a dead {CULTURE_KHU} pays nothing. A chained one pays in {CULTURE_ASE} ports, in coastal markets, in the hands of any man who has reason to want a steppe-rider broken. The trade is cleaner than vengeance because the trade does not end. Vengeance ends the moment the throat is cut. The ledger goes on.\n\nSo that is what pays me into this. Blood that asked to be answered, and a craft that pays better than honest hunting ever did. I run the same line my father ran. I just bring the deer back alive."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_212", "What Targud Hears on the Wind"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_213", "The {CULTURE_KHU} outrider lines have gone thin north of the Amprela ford. Two patrols cut down to one rider, the other pulled south for some khan-quarrel I don't track. A wolf knows when the deer-trail is quiet. I take the ford road at dusk now, three nights running, and the snow keeps what I leave behind.\n\nThere is a merchant in Ortongard who buys without asking the mark on the wrist. {CULTURE_VLA} by tongue, steppe by purse. He pays in silver and old {CULTURE_KHU} coin, and he does not haggle on women under twenty winters. I sold him four last moon. He wants more, and he wants them quiet — no bruised mouths, no broken teeth. The buyers behind him eat with cleaner hands than mine.\n\nA caravan runs the <span style=\"BandItPlus.Place\">Makeb</span>-to-<span style=\"BandItPlus.Place\">Odokh</span> line every ten days, salt and hides, three guards only. The lead guard drinks. I watched him from a ridge two hunts ago and counted the times his head dropped. Six. A pack of four could take it without losing a tooth. I have not moved on it because I am circling fatter prey, but the trail is there for whoever reads it first.\n\nWord from the wind: <span style=\"BandItPlus.Name\">Boyar Urkhun</span>'s youngest son rode out with a hawking party and has not come back. The boyar is offering {CULTURE_KHU} gold for word of him. I think the boy is already in someone's cage, sold east toward {CULTURE_ASE} mouths, and the boyar will pay twice — once for the rumor, once for the bones. That is a ledger I would write in carefully.\n\nTwo other traders work this stretch. One is a {CULTURE_STU} called Hrolf who takes only men and only for the pits — he and I do not cross paths, we cross trades. The other calls himself a caravan-master but moves more chained throats than barrels. He is sloppy. He will be hunted by his own buyers inside a season, and when he is, his routes will be free for the taking. I am patient. Wolves are patient."),
                T1HeroPool = new[] { "wanderer_khuzait_3" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_214", "Erden Long-Tooth"), CharacterTemplateId = "steppe_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_215", "Killed three {CULTURE_KHU} nobles in a single winter and kept their daggers.") },
                TroopT1 = new[] { "steppe_bandit" }, TroopT2 = new[] { "mounted_bandit" }, TroopT3 = new[] { "mounted_bandit" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_216}Three {CULTURE_KHU}s dead. Six prisoners.", "{=bp_slaverprofiles_217}Targud claps your shoulder.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "khuzait", Count = 3, Description = "Slay 3 {CULTURE_KHU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_218}{CULTURE_KHU} lord alive. Five dead. Twenty flax.", "{=bp_slaverprofiles_219}Targud howls a laugh.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_KHU} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "khuzait", Count = 5, Description = "Slay 5 {CULTURE_KHU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "flax_bundle", Count = 20, Description = "Gather 20 flax bundles" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_220}Twelve dead, fifteen alive, the lord, fifty flax.", "{=bp_slaverprofiles_221}Targud opens the pack-hold.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "khuzait", Count = 12, Description = "Slay 12 {CULTURE_KHU}s" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked {CULTURE_KHU} ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "flax_bundle", Count = 50, Description = "Gather 50 flax bundles" }),
            },

            ["bp_pagan_cult"] = new SlaverProfile
            {
                CultureId = "bp_pagan_cult", Name = BandItPlus.Localization.Get("bp_slaverprofiles_222", "Old Crone Hessa"), Title = BandItPlus.Localization.Get("bp_slaverprofiles_223", "Bone-Reckoner"),
                Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_224", "Has lived too long. Trades in souls — by which she means people. Her smile is colder than the chief's blade."),
                GateSpeech = "{=bp_slaverprofiles_225}The bones say you'll do work. Show them they aren't liars.",
                CellarFlavor = BandItPlus.Localization.Get("bp_slaverprofiles_226", "Hessa's cellar is round, walls painted with marks no living tongue still reads. The prisoners sit in a circle facing inward toward a brazier that never quite goes out. Each one wears a small bone token at their throat — Hessa's mark, she says. \"Tells the dead which ones are mine.\" None of the prisoners speak. One of them is humming. Hessa hums along."),
                SelfStoryTitle = BandItPlus.Localization.Get("bp_slaverprofiles_227", "What the Bones Paid"),
                SelfStoryBody = BandItPlus.Localization.Get("bp_slaverprofiles_228", "The bones taught me first. My mother threw them on a wolfskin when I was small, and the marks told her my brother would die before the snow. He did. She threw them again and they told her the price a {CULTURE_BAT} sword-merchant would pay for her second daughter. He paid it. That is the first thing I learned about the trade — the bones do not lie, and the buyers do not haggle when the marks are read true.\n\nI read them for the cult after she went into the grove and did not come back. Old women read bones; old women read men. There is little difference. A skull cracks the same way a purse does — a clean break along the seam, and out spills what was kept inside. I sat by the fire and I told the chiefs which captives would fetch coin in <span style=\"BandItPlus.Place\">Pravend</span> and which were only good for the altar. I was right more often than I was wrong. They began to bring me the live ones first, and the dead ones after.\n\nA soul has a weight, you see. I do not mean the priest's weight, the breath-and-light nonsense. I mean the weight in the hand when you grip a wrist and the pulse runs against your thumb. That weight is what I trade. I have held boys who weighed nothing and old men who weighed more than their chains. The bones tell me which is which before I ever lay a finger.\n\nI have lived too long for warmth. My husband is forty winters in the ground, my daughters scattered to four cultures, and the grove keeps the cold out of my hut better than any hearth. What is left for a woman like me but the ledger? I tally. I read. I sell. The coin goes to the cult and the cult feeds me, and when the bones finally say my own name I will lie down in the grove and stop counting.\n\nSo that is what pays a man into this trade — or a woman, since you asked it of me. Hunger paid me first. The bones paid me after. And now habit pays me, which is the heaviest coin of the three."),
                NewsRumorsTitle = BandItPlus.Localization.Get("bp_slaverprofiles_229", "What the Bones Hear"),
                NewsRumorsBody = BandItPlus.Localization.Get("bp_slaverprofiles_230", "The bones spoke last night. Three vertebrae fell toward the east road — {CULTURE_BAT} wool wagons crossing without enough spears. I read four guards, maybe five, and one of them limps in his left hip. The merchant who pays them is too thin in the purse to hire more. That road runs ripe for whoever has the stomach to cut the traces.\n\nA lord south of here drinks himself stupid every third night. His hall is half-empty, his huscarls scattered chasing a feud he started drunk. I have heard his name twice in a week from travelers who didn't know they were telling me anything. A man like that loses daughters and stableboys before the harvest, and the bones don't lie about which way his hall is tipping.\n\nThe salt town down the coast — they buy quiet now. Their reeve has a back room and a coin scale, and he does not ask after the mark on a wrist or where the chain came from. Bring him strong arms and young backs. He pays in clipped silver, but the silver is real, which is more than I say of half the buyers between here and the river.\n\nThere is a {CULTURE_VLA} who calls himself a horse-dealer working two valleys west. He is no horse-dealer. He moves what I move, and he moves it cheap, which means he steals more than he buys. The bones say he will hang inside a year. Until then, do not undercut him on his own road — he keeps three killers and a dog that does not bark before it bites.\n\nAnd the caravan out of the river-fort — the one that runs every new moon with the priests' tithe? Their captain was buried last week. The new one is a boy. The bones rattled when I asked after him. That is the sort of rattle that means a ledger waiting to be filled."),
                T1HeroPool = new[] { "wanderer_battanian_2", "wanderer_imperial_3" }, T2PrisonerCriteria = "tier>=2,any_kingdom",
                T3UniqueHero = new UniqueHeroSpec { Name = BandItPlus.Localization.Get("bp_slaverprofiles_231", "The Marked-Brother"), CharacterTemplateId = "forest_bandit", Backstory = BandItPlus.Localization.Get("bp_slaverprofiles_232", "Bears scars Hessa carved when he was a boy. He doesn't remember why.") },
                TroopT1 = new[] { "forest_bandit" }, TroopT2 = new[] { "forest_bandit_raider" }, TroopT3 = new[] { "forest_bandit_veteran" },
                QuestT1 = NewQuest("{=bp_slaverprofiles_233}Three of any blood. Six prisoners. The bones don't care.", "{=bp_slaverprofiles_234}Hessa cackles, pays in old coin.", 2000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 3, Description = BandItPlus.Localization.Get("bp_hcs_015", "Kill 3 lords (any culture)") },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 6, Description = "Deliver 6 prisoners" }),
                QuestT2 = NewQuest("{=bp_slaverprofiles_235}A lord alive. Five dead. Twenty hardwood for the pyres.", "{=bp_slaverprofiles_236}Hessa smiles slowly.", 5000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked lord ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 5, Description = "Kill 5 lords" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 20, Description = "Gather 20 hardwood" }),
                QuestT3 = NewQuest("{=bp_slaverprofiles_237}Twelve dead, fifteen alive, the lord, fifty hardwood. The bones whisper.", "{=bp_slaverprofiles_238}Hessa opens the deep-stone door.", 10000,
                    new ObjectiveSpec { Kind = ObjectiveKind.Kill, CultureFilter = "*", Count = 12, Description = "Kill 12 lords" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Capture, TargetId = "RUNTIME_PICK", Count = 1, Description = "Capture marked lord ALIVE" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Prisoners, Count = 15, Description = "Deliver 15 prisoners" },
                    new ObjectiveSpec { Kind = ObjectiveKind.Materials, TargetId = "hardwood", Count = 50, Description = BandItPlus.Localization.Get("bp_hcs_016", "Gather 50 hardwood") }),
            },
        };

        // Helper to compact compound-quest construction across the 13 culture entries.
        private static SlaverCompoundQuest NewQuest(string intro, string thanks, int gold, params ObjectiveSpec[] objs)
        {
            return new SlaverCompoundQuest
            {
                IntroText = intro,
                ThanksText = thanks,
                RewardGold = gold,
                Objectives = objs,
            };
        }
    }
